PRAGMA foreign_keys=ON;
BEGIN IMMEDIATE;
CREATE TABLE read_place_entrance(place_id TEXT NOT NULL REFERENCES entity(id),entrance_id TEXT NOT NULL REFERENCES entity(id),access_fact_id TEXT NOT NULL REFERENCES fact(id),PRIMARY KEY(place_id,entrance_id));
CREATE TABLE read_transit_route(route_id TEXT PRIMARY KEY REFERENCES entity(id),shape_fact_id TEXT NOT NULL REFERENCES fact(id),calendar_fact_id TEXT NOT NULL REFERENCES fact(id));
CREATE TABLE read_transit_stop(route_id TEXT NOT NULL REFERENCES read_transit_route(route_id),sequence INTEGER NOT NULL CHECK(sequence>=0),stop_id TEXT NOT NULL REFERENCES entity(id),sequence_fact_id TEXT NOT NULL REFERENCES fact(id),PRIMARY KEY(route_id,sequence));
CREATE TRIGGER read_entrance_guard BEFORE INSERT ON read_place_entrance WHEN NOT EXISTS(SELECT 1 FROM entity p JOIN entity e ON e.id=new.entrance_id JOIN fact f ON f.id=new.access_fact_id WHERE p.id=new.place_id AND p.kind='place' AND e.kind='entrance' AND f.subject_id=p.id AND f.property='entrance_access' AND f.knowledge='asserted' AND json_extract(f.value_json,'$.entrance_id')=e.id AND json_extract(f.value_json,'$.eligible')=1 AND json_extract(f.value_json,'$.access')='public') BEGIN SELECT RAISE(ABORT,'unbound place entrance access'); END;
CREATE TRIGGER read_route_guard BEFORE INSERT ON read_transit_route WHEN NOT EXISTS(SELECT 1 FROM entity e JOIN fact s ON s.id=new.shape_fact_id JOIN fact c ON c.id=new.calendar_fact_id WHERE e.id=new.route_id AND e.kind='transit_route' AND s.subject_id=e.id AND s.property='route_shape' AND s.knowledge='asserted' AND json_extract(s.value_json,'$.crs')='EPSG:4326' AND json_type(s.value_json,'$.coordinates')='array' AND c.subject_id=e.id AND c.property='calendar' AND c.knowledge='asserted' AND json_type(c.value_json,'$.description')='text') BEGIN SELECT RAISE(ABORT,'unbound transit shape/calendar'); END;
CREATE TRIGGER read_stop_guard BEFORE INSERT ON read_transit_stop WHEN NOT EXISTS(SELECT 1 FROM entity e JOIN fact f ON f.id=new.sequence_fact_id WHERE e.id=new.stop_id AND e.kind='transit_stop' AND f.subject_id=new.route_id AND f.property='route_stop_sequence' AND f.knowledge='asserted' AND EXISTS(SELECT 1 FROM json_each(f.value_json) j WHERE json_extract(j.value,'$.stop_id')=e.id AND json_extract(j.value,'$.sequence')=new.sequence)) BEGIN SELECT RAISE(ABORT,'unbound transit stop sequence'); END;
CREATE TRIGGER read_entrance_immutable BEFORE UPDATE ON read_place_entrance BEGIN SELECT RAISE(ABORT,'read projection immutable; install new pack'); END;
CREATE TRIGGER read_route_immutable BEFORE UPDATE ON read_transit_route BEGIN SELECT RAISE(ABORT,'read projection immutable; install new pack'); END;
CREATE TRIGGER read_stop_immutable BEFORE UPDATE ON read_transit_stop BEGIN SELECT RAISE(ABORT,'read projection immutable; install new pack'); END;
INSERT INTO schema_migration VALUES(3,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
COMMIT;
